-- ============================================================
-- AI School - FULL RESET of the finance section + import from AI_School.xlsx (v3, 2026-10-10)
-- !!! This DELETES ALL finance data first: expenses (+versions, approvals, attachment
-- records), expense categories, budget lines, staff + departments, partner funding,
-- subscription revenue and manual journal entries. Users/roles/other modules are untouched.
-- TAKE A DB BACKUP FIRST. Safe to re-run (it always rebuilds from scratch).
--
-- Chart: 5100 operations subscriptions | 5200 educational-content team (per achievement)
--        5300 marketing & graphic (fixed salary + bonus + per-piece design)
--        5400 customer service (fixed salary + 50 SAR/student commission)
--        5500 teachers (15 SAR/session + commissions & overtime)
--        5600 campaigns & marketing materials | 5700 other (5710 international transfer fees)
-- Payroll: month N is transferred in month N+1 -> period_month = N (accrued at month end).
-- Transfer fee: fixed 17.25 per transfer, one standalone 5710 expense per transfer day,
-- not linked to any person.
-- Expected: 87 expenses = 74122.62 SAR, funding 72942.00, revenue 4640.00, 3 budget lines.
-- ============================================================
BEGIN;
DELETE FROM journal_lines;
DELETE FROM journal_entries;
DELETE FROM expense_attachments;
DELETE FROM expense_approvals;
DELETE FROM expense_versions;
DELETE FROM expenses;
DELETE FROM budget_line_categories;
DELETE FROM budget_line_approvals;
DELETE FROM budget_lines;
DELETE FROM expense_categories WHERE parent_id IS NOT NULL;
DELETE FROM expense_categories;
DELETE FROM staff_members;
DELETE FROM staff_departments;
DELETE FROM finance_funding;
DELETE FROM finance_revenues;
DO $$
DECLARE admin_id uuid;
BEGIN
  SELECT id INTO admin_id FROM users ORDER BY created_at ASC LIMIT 1;
  IF admin_id IS NULL THEN RAISE EXCEPTION 'No user found to attribute the import to'; END IF;

  SELECT gen_random_uuid(), e.id, 1, jsonb_build_object(
      'amount', e.amount::text, 'currency', e.currency, 'expense_date', to_char(e.expense_date, 'YYYY-MM-DD'),
      'category_id', e.category_id::text, 'subcategory_id', e.subcategory_id::text, 'budget_line_id', e.budget_line_id::text,
      'staff_id', e.staff_id::text, 'description', e.description, 'vendor', e.vendor, 'invoice_number', e.invoice_number,
      'payment_method', e.payment_method, 'notes', e.notes, 'invoice_date', NULL, 'invoice_url', e.invoice_url,
      'paid_by', e.paid_by, 'period_month', e.period_month, 'breakdown', e.breakdown, 'status', e.status),
    'استيراد من ملف AI_School.xlsx', NULL, admin_id, now()
  FROM expenses e;
END $$;

-- ---------------- checks ----------------
SELECT c.code, c.name, count(*) AS rows, sum(e.amount) AS total
FROM expenses e JOIN expense_categories c ON c.id = e.category_id GROUP BY c.code, c.name ORDER BY c.code;
SELECT (SELECT sum(amount) FROM expenses) AS expenses_total, 74122.62 AS expected,
       (SELECT count(*) FROM expenses) AS expense_rows, 87 AS expected_rows,
       (SELECT sum(amount) FROM finance_funding) AS funding, (SELECT sum(amount) FROM finance_revenues) AS revenue,
       (SELECT count(*) FROM staff_members) AS staff, (SELECT count(*) FROM budget_lines) AS budget_lines;
COMMIT;
